css:
.loader {
  position: relative;
  width: 44px;
  height: 52px;
  transform-origin: top center;
  animation: swing 1.6s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 12px;
  height: 12px;
  margin-left: -6px;
  border: 3px solid #6366f1;
  border-radius: 50%;
  box-sizing: border-box;
}
.loader i {
  position: absolute;
  top: 12px;
  left: 50%;
  width: 4px;
  height: 30px;
  margin-left: -2px;
  border-radius: 2px;
  background: #6366f1;
}
.loader i::before {
  content: "";
  position: absolute;
  top: 4px;
  left: -9px;
  width: 22px;
  height: 4px;
  border-radius: 2px;
  background: #6366f1;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: -13px;
  width: 30px;
  height: 16px;
  border: 4px solid #6366f1;
  border-top: 0;
  border-radius: 0 0 50% 50%;
  box-sizing: border-box;
}
@keyframes swing {
  0%, 100% { transform: rotate(-14deg); }
  50% { transform: rotate(14deg); }
}
